import{_ as a,o as n,c as e,a0 as t}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"Sandbox Architecture","description":"","frontmatter":{"title":"Sandbox Architecture"},"headers":[],"relativePath":"design/sandbox.md","filePath":"design/sandbox.md"}'),o={name:"design/sandbox.md"};function r(i,s,p,d,l,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="sandbox-architecture" tabindex="-1">Sandbox Architecture <a class="header-anchor" href="#sandbox-architecture" aria-label="Permalink to &quot;Sandbox Architecture&quot;">​</a></h1><blockquote><p>Source: <code>cmd/lattice/cmd/sandbox/</code>, <code>internal/agent/gvisor/</code>, <code>internal/agent/runsc/</code></p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>lattice sandbox start</code> supports two isolation modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Flag</th><th>Isolation mechanism</th><th>Network stack</th></tr></thead><tbody><tr><td><strong>pod</strong></td><td><code>--mode pod</code></td><td>gVisor user-space netstack (in-process)</td><td>gVisor <code>pkg/tcpip</code> + TUNAdapter</td></tr><tr><td><strong>gvisor</strong></td><td><code>--mode gvisor</code></td><td>gVisor runsc container (<code>--network=host</code>)</td><td>Pod kernel WireGuard (real <code>/dev/net/tun</code>)</td></tr></tbody></table><p>Both modes give AI agents a full Lattice network identity — NATS registration, ICE hole-punching, LRP relay fallback — identical to a regular node.</p><h2 id="gvisor-mode-runsc-two-phase-architecture" tabindex="-1">gVisor Mode (runsc): Two-Phase Architecture <a class="header-anchor" href="#gvisor-mode-runsc-two-phase-architecture" aria-label="Permalink to &quot;gVisor Mode (runsc): Two-Phase Architecture&quot;">​</a></h2><p>gVisor cannot simultaneously provide K8s network access (<code>--network=host</code>) and a virtual TUN device (<code>--network=sandbox</code>). The solution splits work into two phases:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 1 (pod kernel):                    Phase 2 (runsc container):</span></span>
<span class="line"><span>┌──────────────────────────┐            ┌─────────────────────────────┐</span></span>
<span class="line"><span>│  bootstrapAgent()        │            │  runsc --network=host        │</span></span>
<span class="line"><span>│                          │            │                             │</span></span>
<span class="line"><span>│  ① NATS registration    │            │  PID 1: AI agent binary      │</span></span>
<span class="line"><span>│  ② wireguard-go → wg0   │            │  (direct exec, no shim)      │</span></span>
<span class="line"><span>│     (real /dev/net/tun)  │            │                             │</span></span>
<span class="line"><span>│  ③ Routes + iptables    │            │  AI agent connect(peer)      │</span></span>
<span class="line"><span>│                          │            │    → gVisor sentry           │</span></span>
<span class="line"><span>│  node stays alive ───────┼────────────▶   → host kernel passthrough │</span></span>
<span class="line"><span>│                          │            │    → pod routing             │</span></span>
<span class="line"><span>└──────────────────────────┘            │    → wg0 → overlay           │</span></span>
<span class="line"><span>                                        └─────────────────────────────┘</span></span></code></pre></div><p><strong>Key property</strong>: WireGuard runs on the real kernel, not inside gVisor. The AI agent in gVisor inherits the pod&#39;s network namespace via <code>--network=host</code>, so its traffic follows the pod&#39;s routes into wg0 and the overlay. gVisor&#39;s sentry intercepts all syscalls for security isolation, but networking no longer depends on gVisor&#39;s internal netstack.</p><h3 id="ai-agent-traffic-path-gvisor-mode" tabindex="-1">AI agent traffic path (gVisor mode) <a class="header-anchor" href="#ai-agent-traffic-path-gvisor-mode" aria-label="Permalink to &quot;AI agent traffic path (gVisor mode)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI agent connect(peer-ip:port)</span></span>
<span class="line"><span>  → gVisor sentry (syscall interposition, security policy)</span></span>
<span class="line"><span>  → host kernel passthrough (--network=host)</span></span>
<span class="line"><span>  → pod routing table</span></span>
<span class="line"><span>  → wg0 (real WireGuard, pod kernel)</span></span>
<span class="line"><span>  → UDP :51820 → WireGuard peer → overlay</span></span></code></pre></div><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Mechanism</th></tr></thead><tbody><tr><td>Syscall isolation</td><td>gVisor sentry (all syscalls intercepted)</td></tr><tr><td>Network access</td><td>Pod iptables/eBPF rules on wg0</td></tr><tr><td>WireGuard keys</td><td>On pod kernel, not in gVisor</td></tr><tr><td>CAP_NET_ADMIN</td><td>Not granted to gVisor container</td></tr></tbody></table><h2 id="pod-mode-in-process-gvisor-netstack" tabindex="-1">pod Mode (in-process gVisor netstack) <a class="header-anchor" href="#pod-mode-in-process-gvisor-netstack" aria-label="Permalink to &quot;pod Mode (in-process gVisor netstack)&quot;">​</a></h2><p>The original architecture uses an in-process gVisor netstack. WireGuard runs in user-space with a TUN adapter bridging gVisor&#39;s network stack to the WireGuard device.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌─────────────────────────────┐</span></span>
<span class="line"><span>                │       gVisor Sandbox         │</span></span>
<span class="line"><span>                │                              │</span></span>
<span class="line"><span>  Agent process ──▶  gVisor netstack (tcpip)   │</span></span>
<span class="line"><span>  connect()         │                          │</span></span>
<span class="line"><span>                │  [Pro] EgressFilter          │</span></span>
<span class="line"><span>                │   │                          │</span></span>
<span class="line"><span>                │   TUNAdapter (channel bridge)│</span></span>
<span class="line"><span>                │   │                          │</span></span>
<span class="line"><span>                │   wireguard-go Device        │</span></span>
<span class="line"><span>                └──────────┬───────────────────┘</span></span>
<span class="line"><span>                           │ UDP :51820</span></span>
<span class="line"><span>                ┌──────────▼───────────────────┐</span></span>
<span class="line"><span>                │   FilteringUDPMux             │</span></span>
<span class="line"><span>                │   STUN ──▶ ICE agent          │</span></span>
<span class="line"><span>                │   non-STUN ──▶ WG DefaultBind │</span></span>
<span class="line"><span>                └──────────┬───────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>          ┌────────────────┴──────────────┐</span></span>
<span class="line"><span>          │  ICE succeeds                 │  ICE fails</span></span>
<span class="line"><span>          ▼                               ▼</span></span>
<span class="line"><span>    Direct P2P                    LRP relay (QUIC/TCP)</span></span></code></pre></div><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Regular Node</th><th>pod mode</th><th>gvisor mode</th></tr></thead><tbody><tr><td>Isolation</td><td>None</td><td>gVisor netstack (in-process)</td><td>runsc container</td></tr><tr><td>Privilege</td><td>root / <code>CAP_NET_ADMIN</code></td><td><strong>Zero-privilege</strong></td><td><strong>Zero-privilege</strong></td></tr><tr><td>Network stack</td><td>Kernel TUN (<code>wf0</code>)</td><td>gVisor <code>pkg/tcpip</code> + TUNAdapter</td><td>Pod kernel TUN (real wg0)</td></tr><tr><td>WireGuard</td><td>Kernel <code>wgctrl</code></td><td><code>wireguard-go</code> (user-space)</td><td><code>wireguard-go</code> (pod kernel)</td></tr><tr><td>Provisioner</td><td><code>KernelProvisioner</code> (iptables/eBPF)</td><td><code>SandboxProvisioner</code> (no iptables)</td><td><code>KernelProvisioner</code> (pod iptables/eBPF)</td></tr><tr><td>Registration</td><td>HTTP or NATS</td><td>NATS only</td><td>NATS only</td></tr><tr><td>Credential persistence</td><td>None</td><td>JSON file</td><td>JSON file</td></tr><tr><td>SOCKS5 proxy</td><td>None</td><td>Optional</td><td>None (direct routing)</td></tr><tr><td>Inbound forwarding</td><td>None</td><td>Optional (Pro)</td><td>None</td></tr><tr><td>Egress policy</td><td>eBPF TC (Pro) / iptables</td><td><code>EgressFilter</code> (Pro)</td><td>Pod iptables/eBPF</td></tr><tr><td>ICE / LRP</td><td>Full support</td><td>Full support</td><td>Full support</td></tr></tbody></table><h2 id="code-structure" tabindex="-1">Code Structure <a class="header-anchor" href="#code-structure" aria-label="Permalink to &quot;Code Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmd/lattice/cmd/sandbox/</span></span>
<span class="line"><span>├── sandbox.go              # Command definition (--name, --server-url, --token, --mode)</span></span>
<span class="line"><span>├── sandbox_shared.go       # No build tag — shared utilities (credential I/O, fileAuditWriter)</span></span>
<span class="line"><span>├── sandbox_community.go    # //go:build !pro — full community implementation (pod mode)</span></span>
<span class="line"><span>├── sandbox_pro.go          # //go:build pro  — Pro-only extensions (both modes)</span></span>
<span class="line"><span>├── sandbox_agent.go        # //go:build pro  — \`lattice sandbox agent\` (manual debugging)</span></span>
<span class="line"><span>├── driver.go               # DriverConfig, IsolationDriver interface</span></span>
<span class="line"><span>├── driver_pod.go           # //go:build pro  — PodDriver (in-process gVisor netstack)</span></span>
<span class="line"><span>└── driver_runsc.go         # //go:build pro  — RunscDriver (two-phase bootstrap + runsc)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>internal/agent/</span></span>
<span class="line"><span>├── gvisor/                 # In-process gVisor netstack (pod mode)</span></span>
<span class="line"><span>│   ├── sandbox.go          # gvisor.New() entry point</span></span>
<span class="line"><span>│   ├── tun_adapter.go      # TUNAdapter: gVisor ↔ wireguard-go packet bridge</span></span>
<span class="line"><span>│   └── provisioner.go      # SandboxProvisioner (no iptables, replaces KernelProvisioner)</span></span>
<span class="line"><span>└── runsc/                  # runsc OCI container lifecycle (gvisor mode)</span></span>
<span class="line"><span>    └── runsc.go            # Manager: OCI spec generation, runsc start/stop</span></span></code></pre></div><h2 id="community-vs-pro-build-tags" tabindex="-1">Community vs Pro Build Tags <a class="header-anchor" href="#community-vs-pro-build-tags" aria-label="Permalink to &quot;Community vs Pro Build Tags&quot;">​</a></h2><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sandbox_community.go</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//go:build !pro</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sandbox_pro.go, sandbox_agent.go, driver_pod.go, driver_runsc.go</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//go:build pro</span></span></code></pre></div><p>Community stubs for Pro features return <code>&quot;... is a Pro feature&quot;</code> errors. Build with <code>make EDITION=pro build</code> to include Pro code.</p>`,24)])])}const h=a(o,[["render",r]]);export{u as __pageData,h as default};
